package com.creditsense.domain;
import jakarta.persistence.*; import com.fasterxml.jackson.annotation.JsonIgnore; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="applicants") public class Applicant { @Id private UUID id=UUID.randomUUID(); @JsonIgnore @OneToOne @JoinColumn(name="user_id",nullable=false) private User user; @Column(name="business_name") private String businessName; @Column(length=10,nullable=false) private String pan; @Column(length=15,nullable=false) private String gstin; @Column(nullable=false) private String address; private boolean blacklisted; @Column(name="created_at") private Instant createdAt=Instant.now(); public Applicant(){} public UUID getId(){return id;} public User getUser(){return user;} public String getBusinessName(){return businessName;} public String getPan(){return pan;} public String getGstin(){return gstin;} public String getAddress(){return address;} public boolean isBlacklisted(){return blacklisted;} public void setUser(User v){user=v;} public void setBusinessName(String v){businessName=v;} public void setPan(String v){pan=v;} public void setGstin(String v){gstin=v;} public void setAddress(String v){address=v;} public void setBlacklisted(boolean v){blacklisted=v;} }
